function buildEntry(id, def) {
  const rootNames = ROOTS[id] || (id === DEFAULT_INSTRUMENT ? PIANO_ROOTS : null);
  if (!rootNames || !rootNames.length) return null;
  const roots = rootNames
    .map((name) => ({ name, midi: noteNameToMidi(name) }))
    .sort((a, b) => a.midi - b.midi);
  const lo = roots[0].midi - STRETCH;
  const hi = roots[roots.length - 1].midi + STRETCH;
  return { id, ...def, roots, range: def.range || { lo, hi } };
}

// The Salamander piano predates the generated-roots mechanism (it isn't
// fetched by tools/fetch_instruments.mjs, which only vendors the tonejs set)
// so its root list is hand-kept here rather than in the generated file.
const PIANO_ROOTS = [
  'A0', 'C1', 'D#1', 'F#1',
  'A1', 'C2', 'D#2', 'F#2',
  'A2', 'C3', 'D#3', 'F#3',
  'A3', 'C4', 'D#4', 'F#4',
  'A4', 'C5', 'D#5', 'F#5',
  'A5', 'C6', 'D#6', 'F#6',
  'A6', 'C7', 'D#7', 'F#7',
  'A7', 'C8',
];

export const INSTRUMENTS = Object.entries(META)
  .map(([id, def]) => buildEntry(id, def))
  .filter(Boolean)
  .sort((a, b) => {
    const g = GROUP_ORDER.indexOf(a.group) - GROUP_ORDER.indexOf(b.group);
    return g !== 0 ? g : a.order - b.order;
  });

const BY_ID = new Map(INSTRUMENTS.map((i) => [i.id, i]));

/** Look up an instrument by id, falling back to the default piano for any unknown id. */
export function instrumentById(id) {
  return BY_ID.get(id) || BY_ID.get(DEFAULT_INSTRUMENT);
}

/** Instruments grouped for the dropdown's <optgroup>s, in display order. */
export function instrumentGroups() {
  const map = new Map();
  for (const inst of INSTRUMENTS) {
    if (!map.has(inst.group)) map.set(inst.group, []);
    map.get(inst.group).push(inst);
  }
  return [...map.entries()].map(([group, items]) => ({ group, items }));
}

/**
 * Expand an instrument's filename pattern for one root note (+ velocity
 * layer, if any). Returns the RAW on-disk filename — '#' stays literal
 * ("D#1v6.ogg"); percent-encoding for the fetch URL happens separately in
 * audio.js's sampleUrl(), the one place that needs a URL rather than a path.
 */
export function fileFor(def, rootName, layer) {
  return def.pattern
    .replace('{root}', rootName)
    .replace('{sroot}', rootName.replace('#', 's'))
    .replace('{layer}', layer ?? '');
}
